endpoint.request:
{
  collected_amount: number, required, gt:0, max:installment.amount,
  collected_at: date, required,
  residual_mode: "spread" | "new_installment", required se collected_amount minore di amount, altrimenti ignorato,
  residual_due_date: date, required se residual_mode = new_installment, after_or_equal:invoice.document_date
}
